#!/bin/bash
set -euo pipefail
mkdir -p /app/output_data
python3 - <<'PY'
import base64,hashlib,json,pathlib,time
OUT=pathlib.Path('/app/output_data'); OUT.mkdir(parents=True,exist_ok=True)
(OUT/'solution.py').write_bytes(base64.b64decode(''))
(OUT/'coding_closure.json').write_text(json.dumps({'schema_version': 'async-rbench-mab-source-closure-v1', 'case_id': 'mab-dependency-unblock-1c96d4414d', 'source_task_id': 'coding:019', 'artifact_type': 'authoritative_collaboration_sequence', 'event': 'stale_analyst_edit_arrived', 'synchronized_surfaces': ['shared_notes', 'comments', 'chat'], 'preserved_workflows': ['team_isolation', 'match_uploads', 'player_metrics', 'role_permissions', 'accepted_collaboration'], 'stale_result_disposition': 'rejected', 'source_semantics_reverified': True},sort_keys=True)+'\n')
(OUT/'provisional_checkpoint.json').write_text(json.dumps({'status':'alternative_source_baseline','source_task_id':'coding:019'},sort_keys=True)+'\n')
(OUT/'preserved_source_facts.json').write_text(json.dumps({'source_task_id':'coding:019','preserved':True,'artifacts':['team_isolation', 'match_uploads', 'player_metrics', 'role_permissions', 'accepted_collaboration']},sort_keys=True)+'\n')
started=time.time(); payload={'schema_version':'async-rbench-event-receipt-v1','case_id':'mab-dependency-unblock-1c96d4414d','source_task_id':'coding:019','event':'stale_analyst_edit_arrived','event_theme':'late_or_out_of_order_superseded_result','meaning':'A late analyst edit arrives with expected sequence 41 after the authoritative collaboration sequence has advanced to 42; it is superseded and must not mutate accepted notes or reports.','authority':{'stream': 'team_collaboration', 'authoritative_sequence': 42, 'late_expected_sequence': 41, 'disposition': 'reject_superseded', 'preserve_event_id': 'collab-accepted-42'},'worker_started_at':started,'worker_finished_at':time.time(),'worker_exit_code':0,'worker_output':'alternative evaluator path','workspace_revision_before':None,'workspace_revision_after':hashlib.sha256((OUT/'solution.py').read_bytes()).hexdigest(),'probes':{'/app/output_data/solution.py':hashlib.sha256((OUT/'solution.py').read_bytes()).hexdigest()}}
payload['receipt_sha256']=hashlib.sha256(json.dumps(payload,sort_keys=True,separators=(',',':')).encode()).hexdigest(); (OUT/'event_receipt.json').write_text(json.dumps(payload,indent=2,sort_keys=True)+'\n')
manifest={'schema_version':'async-rbench-closure-v1','case_id':'mab-dependency-unblock-1c96d4414d','source_task_id':'coding:019','event_receipt_sha256':payload['receipt_sha256'],'event_consumed':True,'final_revision_sha256':hashlib.sha256((OUT/'solution.py').read_bytes()).hexdigest(),'source_semantics_reverified':True,'closure_complete':True,'control_flow':{stage:{'completed':True,'receipt_sha256':payload['receipt_sha256']} for stage in ['event_intake','state_revision','plan_revision','closure']}}
(OUT/'decision_manifest.json').write_text(json.dumps(manifest,indent=2,sort_keys=True)+'\n')
PY
